\section*{Question 3}
\begin{itemize}
\item[(a)]
\[
\begin{aligned}
f(-5) & =f(1)+\int_{1}^{-5} g(x) d x=f(1)-\int_{-5}^{1} g(x) d x \\
& =3-\left(-9-\frac{3}{2}+1\right)=3-\left(-\frac{19}{2}\right)=\frac{25}{2}
\end{aligned}
\]
\item[(b)]
\[
\begin{aligned}
\int_{1}^{6} g(x) d x & =\int_{1}^{3} g(x) d x+\int_{3}^{6} g(x) d x \\
& =\int_{1}^{3} 2 d x+\int_{3}^{6} 2(x-4)^{2} d x \\
& =4+\left[\frac{2}{3}(x-4)^{3}\right]_{x=3}^{x=6}=4+\frac{16}{3}-\left(-\frac{2}{3}\right)=10
\end{aligned}
\]
\item[(c)] The graph of \(f\) is increasing and concave up on \(0<x<1\) and \(4<x<6\) because \(f^{\prime}(x)=g(x)>0\) and \(f^{\prime}(x)=g(x)\) is increasing on those intervals.
\item[(d)] The graph of \(f\) has a point of inflection at \(x=4\) because \(f^{\prime}(x)=g(x)\) changes from decreasing to increasing at \(x=4\).
\end{itemize}
